{

    internal InnerOAuth2CredentialProviderIncludedOauth2ProviderConfigInputFactory IncludedOauth2ProviderConfigFactory { get; set; }

    internal InnerOAuth2CredentialProviderGoogleOauth2ProviderConfigInputFactory GoogleOauth2ProviderConfigFactory { get; set; }

    internal InnerOAuth2CredentialProviderGithubOauth2ProviderConfigInputFactory GithubOauth2ProviderConfigFactory { get; set; }

