    internal InnerOAuth2CredentialProviderLinkedinOauth2ProviderConfigInputFactory LinkedinOauth2ProviderConfigFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.Oauth2ProviderConfigInput Create()
    {
        var oauth2ProviderConfigInputResult = CreateOauth2ProviderConfigInput();
        factoryAction?.Invoke(oauth2ProviderConfigInputResult);

        return oauth2ProviderConfigInputResult;
    }

    private Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.Oauth2ProviderConfigInput CreateOauth2ProviderConfigInput()
    {
        var oauth2ProviderConfigInputResult = new Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.Oauth2ProviderConfigInput();

        return oauth2ProviderConfigInputResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.Oauth2ProviderConfigInput result)
    {
        base.CreateChildren(result);

        result.IncludedOauth2ProviderConfig ??= IncludedOauth2ProviderConfigFactory?.Build();
        result.GoogleOauth2ProviderConfig ??= GoogleOauth2ProviderConfigFactory?.Build();
        result.GithubOauth2ProviderConfig ??= GithubOauth2ProviderConfigFactory?.Build();
        result.MicrosoftOauth2ProviderConfig ??= MicrosoftOauth2ProviderConfigFactory?.Build();
        result.SlackOauth2ProviderConfig ??= SlackOauth2ProviderConfigFactory?.Build();
        result.SalesforceOauth2ProviderConfig ??= SalesforceOauth2ProviderConfigFactory?.Build();
        result.AtlassianOauth2ProviderConfig ??= AtlassianOauth2ProviderConfigFactory?.Build();
        result.CustomOauth2ProviderConfig ??= CustomOauth2ProviderConfigFactory?.Build();
        result.LinkedinOauth2ProviderConfig ??= LinkedinOauth2ProviderConfigFactory?.Build();
    }

} // End Of Class

